frappe.ui.form.on('Payment Entry', {
	refresh(frm) {
		if(frm.doc.party_type =='Customer'){
            frappe.call({
            	method: 'frappe.client.get_list',
            	args: {
            	    doctype: "Sales Invoice",
            	    fields:["name","posting_date","customer","rounded_total","outstanding_amount"],
            	    filters:[["docstatus","=",1], ["customer","=",frm.doc.party], ["outstanding_amount",">",0]] 
            	},
            	async:false,
            	callback(r) {
            	    //frappe.msgprint("Just Look Console");
            	     if(r.message){
                        let outstandings = r.message
                        if(outstandings.length == 0){
                            frappe.msgprint("No Bills Pending. Relax!!!");
                        }
                        else{
                            for(let i = 0;i<outstandings.length;i++){
                                frappe.msgprint(frappe.datetime.get_day_diff(frappe.datetime.get_today(),outstandings[i].posting_date)+ ' days is due for '+ outstandings[i].name);
                      		    frm.add_custom_button(outstandings[i].name, function(){ frappe.msgprint('Outstanding Amount',outstandings[i].outstanding_amount) }
                      		    , __("Outstanding"));
          		            }
                        }
                    }
            	}
            })
        }
	},
	onload(frm) {
        if(frm.doc.party_type =='Customer'){
            frappe.call({
            	method: 'frappe.client.get_list',
            	args: {
            	    doctype: "Sales Invoice",
            	    fields:["name","posting_date","customer","rounded_total","outstanding_amount"],
            	    filters:[["docstatus","=",1], ["customer","=",frm.doc.party], ["outstanding_amount",">",0]] 
            	},
            	async:false,
            	callback(r) {
            	    //frappe.msgprint("Just Look Console");
            	     if(r.message){
                        let outstandings = r.message
                        if(outstandings.length == 0){
                            frappe.msgprint("No Bills Pending. Relax!!!");
                        }
                        else{
                            for(let i = 0;i<outstandings.length;i++){
                                frappe.msgprint(frappe.datetime.get_day_diff(frappe.datetime.get_today(),outstandings[i].posting_date)+ ' days is due for '+ outstandings[i].name);
                      		    frm.add_custom_button(outstandings[i].name, function(){ frappe.msgprint('Outstanding Amount',outstandings[i].outstanding_amount) }
                      		    , __("Outstanding"));
          		            }
                        }
                    }
            	}
            })
        }
    },
    before_save(frm){
        if(frm.doc.paid_to==="Bank Account - SE-K"){
            frappe.throw(__('Bank Account - SE-K is not a valid account. Please select proper Company Account '))
            frm.set_value('paid_to','')
            frm.set_df_property('bank_account', 'reqd', 1)
        }
        if(frm.doc.paid_from==="Bank Account - SE-K"){
            frappe.throw(__('Bank Account - SE-K is not a valid account. Please select proper Company Account '))
            frm.set_value('paid_from','')
            frm.set_df_property('bank_account', 'reqd', 1)
        }
    }
})
frappe.ui.form.on('Payment Entry', 'mode_of_payment', function(frm){
    if(frm.doc.mode_of_payment === 'NEFT'||frm.doc.mode_of_payment === 'UPI'){
        frm.set_df_property('bank_account', 'reqd', 1)
        frm.set_df_property('reference_no','reqd',1)
        frm.set_df_property('reference_date','reqd',1)
    }
    if(frm.doc.mode_of_payment === 'Cheque'){
        frm.set_df_property('reference_no','reqd',1)
        frm.set_df_property('reference_date','reqd',1)
    }
})

frappe.ui.form.on('Sales Invoice', {
	refresh(frm) {
		// your code here
	},
	onload(frm) {
	    //frappe.msgprint(frappe.datetime.get_today())
	    frappe.call({
        	method: 'frappe.client.get_list',
        	args: {
        	    doctype: "Sales Invoice",
        	    fields:["name","posting_date","customer","rounded_total","outstanding_amount"],
        	    filters:[["docstatus","=",1], ["customer","=",frm.doc.customer], ["outstanding_amount",">",0]] 
        	},
        	async:false,
        	callback(r) {
        	    //frappe.msgprint("Just Look Console");
        	     if(r.message){
                    let outstandings = r.message
                    for(let i = 0;i<outstandings.length;i++){
                        if(frappe.datetime.get_day_diff(frappe.datetime.get_today(),outstandings[i].posting_date) != 0){
                            frappe.msgprint(frappe.datetime.get_day_diff(frappe.datetime.get_today(),outstandings[i].posting_date)+ ' days is due for '+ outstandings[i].name);
                        }
              		    frm.add_custom_button(outstandings[i].name, function(){ frappe.msgprint('Outstanding Amount',outstandings[i].outstanding_amount) }
              		    , __("Outstanding"));
  		}
                }
        	}
        })
        if(frm.doc.status == "Draft"){
		frm.doc.update_stock = 1
		frm.refresh_field('update_stock');
	    }
		if(frm.doc.company == 'Sravi Enterprises - Kolapakkam'){
		    frm.doc.set_warehouse = 'Stores - SE-K'
		    frm.refresh_field('set_warehouse');
		}
		frm.doc.apply_discount_on = "Grand Total"
        frm.refresh_field('apply_discount_on');
	}
})

frappe.ui.form.on('Purchase Invoice', {
	refresh(frm) {
		// your code here
	},
	supplier: function(frm){
	    frappe.call({
	        method: 'frappe.client.get',
        	args: {
        	doctype: 'Supplier',
        	name: frm.doc.supplier,
        	},
        	callback: function(r){
        	   // console.log(r.message.is_transporter)
                  is_transporter = r.message.is_transporter;
                  if(is_transporter === 1){
                    frappe.msgprint({
                        title: __('Notification'),
                        indicator: 'green',
                        message: __('Supplier is a Transporter and select an appropriate Freight Cost Center for proper accounting')
                    });
                      frm.set_df_property('cost_center', 'reqd', 1)
                  }
                  if(is_transporter === 0){
                      frm.set_df_property('cost_center', 'reqd', 0)
                  }
                //   console.log(is_transporter);
        	}
	    })
	}
})

frappe.ui.form.on('Expense Claim', {
	refresh(frm) {
		// 1. Check if the user has the 'Field Sales User' role
        if (frappe.user.has_role('Field Sales User')) {
            // 1. Initial toggle on load
            toggle_task_field(frm);
            // 2. Apply a filter to the 'payable_account' link field
            frm.set_query('payable_account', () => {
                return {
                    filters: {
                        'name': 'Expense Claims - SE-K'
                    }
                };
            });

            // 3. Optional: Set the value automatically if it's a new record
            if (frm.is_new()) {
                frm.set_value('payable_account', 'Expense Claims - SE-K');
            }
            // 4. Advanced Filter for Projects
            const project_filter = {
                filters: [
                    ['Project User', 'user', '=', frappe.session.user],
                    ['Project', 'status', '=', 'Open']
                ]
            };

            frm.set_query('project', () => project_filter);
            // The second argument 'expenses' targets the child table
            frm.set_query('project', 'expenses', () => project_filter);
            // 5. SET MANDATORY FIELDS
            frm.set_df_property('project', 'reqd', 1);
            frm.set_df_property('payable_account', 'reqd', 1);
            frm.set_df_property('task', 'reqd', 1);
            frm.set_df_property('clearance_date', 'read_only', 1);
            // 6. Filter Mode of Payment to show only "Credit"
            frm.set_query('mode_of_payment', () => {
                return {
                    filters: [
                        ['Mode of Payment', 'name', 'not like', '%Credit%']
                    ]
                };
            });
        }
	},
	// Triggered when the Project field is changed
    project(frm) {
        toggle_task_field(frm);

        // Clear task value if project is removed/changed to prevent data mismatch
        frm.set_value('task', '');
    }
})
var toggle_task_field = function(frm) {
    if (frm.doc.project) {
        frm.set_df_property('task', 'hidden', 0);
    } else {
        frm.set_df_property('task', 'hidden', 1);
    }
};

frappe.ui.form.on('Timesheet', {
	refresh: function(frm) {
	    // 1. Make Project mandatory on refresh
        frm.set_df_property('parent_project', 'reqd', 1);
        // 2. Filter the main Parent Project field on load
        if (frappe.user.has_role('Field Sales User')) {
            frm.set_query('parent_project', () => {
                return {
                    filters: [
                        ['Project User', 'user', '=', frappe.session.user],
                        ['Project', 'status', '=', 'Open']
                    ]
                };
            });
        }

        //3. Initial visibility check
        toggle_time_logs(frm);
    },

    parent_project: function(frm) {
        // 2. Triggered when the main Project field changes
        toggle_time_logs(frm);

        // Filter the 'project' field inside the child table to match the parent selection
        if (frm.doc.parent_project) {
            frm.set_query('project', 'time_logs', () => {
                return {
                    filters: {
                        'name': frm.doc.parent_project
                    }
                };
            });
        }
    }
})
// Helper function to handle visibility logic
var toggle_time_logs = function(frm) {
    if (frm.doc.parent_project) {
        frm.toggle_display('time_logs', true);
    } else {
        // Hide if no project is selected (if that is your requirement)
        frm.toggle_display('time_logs', false);
    }
};
